mapper.update:
with upsert as (
    update account_vital_history
       set value_num = #{valueNum}
          ,unit = #{unit}
          ,source_cd = #{sourceCd}
          ,memo = #{memo}
          ,updated_at = now()
     where account_seq = #{accountSeq}
       and vital_type_cd = #{vitalTypeCd}
       and measured_at = #{measuredAt}::timestamptz
     returning *
)
insert into account_vital_history (
    account_seq, measured_at, vital_type_cd, value_num, unit, source_cd, memo
)
select #{accountSeq}
      ,#{measuredAt}::timestamptz
      ,#{vitalTypeCd}
      ,#{valueNum}
      ,#{unit}
      ,#{sourceCd}
      ,#{memo}
 where not exists (select 1 from upsert)

mapper.select:
select seq ,account_seq as accountSeq ,to_char(measured_at at time zone 'Asia/Seoul', 'YYYY-MM-DD HH24:MI:SS') as measuredAt ,vital_type_cd as vitalTypeCd ,value_num as valueNum ,unit ,source_cd as sourceCd ,memo ,to_char(created_at at time zone 'Asia/Seoul', 'YYYY-MM-DD HH24:MI:SS') as createdAt from account_vital_history where account_seq = #{accountSeq}
and vital_type_cd = #{vitalTypeCd}
and measured_at >= (#{fromDate}::date at time zone 'Asia/Seoul')
and measured_at < ((#{toDate}::date + interval '1 day') at time zone 'Asia/Seoul')
order by measured_at desc
limit #{limit}
